std::pair<std::vector<std::size_t>, std::vector<double>> closest = tree.closest_point_and_primitive(p, 3);
if (closest.first.empty()) {
    return std::numeric_limits<double>::max();
}

double min_sq_dist = std::numeric_limits<double>::max();
for (std::size_t i = 0; i < closest.first.size(); ++i) {
    const auto& pt = tree.point(closest.first[i]);
    double dx = p.x() - pt.x();
    double dy = p.y() - pt.y();
    double dz = p.z() - pt.z();
    double sq_dist = dx*dx + dy*dy + dz*dz;
    if (sq_dist < min_sq_dist) {
        min_sq_dist = sq_dist;
    }
}

return min_sq_dist;
